# frozen_string_literal: true

require "rails_helper"

# The checkpoint routes: export, load and the round trip between them. Load
# refusals sit in one table so a new refusal reason is one more row.
RSpec.describe "Timekeeping internal handoff checkpoint" do
  include_context "timekeeping entry writes without transactional fixtures"

  # Only the service bearer reaches these routes, and it needs no public key.
  around do |example|
    with_handoff_env(public_key: false) { example.run }
  end

  def checkpoint_from(response)
    Timekeeping::Handoff::Checkpoint.from_json(response.body)
  end

  def checkpoint_spec_entry(note, **attributes)
    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note:, bill_status: "unbilled", source: "manual", source_metadata: {}, **attributes)
  end

  # Acceptance: "Timekeeping exports its entries, reservations, invoice
  # operations, audit rows and idempotency receipts in the canonical checkpoint
  # row shape, each row with company_id"
  it "exports every checkpoint table in the canonical shape with each row under its own company_id" do
    now = Time.utc(2026, 3, 2, 9)
    [11, 22].each do |company_id|
      entry = Entry.create!(company_id:, project_id: 5, user_id: 6, work_date: Date.new(2026, 3, 2), duration: 30.0,
                            bill_status: "unbilled", created_at: now, updated_at: now)
      AuditEvent.create!(company_id:, entry_id: entry.id, actor_type: "user", actor_id: 6, action: "create",
                         before: nil, after: { "duration" => 30.0 }, entry_created_at: now, created_at: now)
      IdempotencyReceipt.create!(company_id:, actor_type: "user", actor_id: 6, operation: "create",
                                 key: "export-key-#{company_id}", fingerprint: "f", status: 201, body: "{}",
                                 created_at: now)
    end

    handoff_request(:checkpoint_export)

    # "Export: return every row of `entries`, `reservations`, `invoice_operations`, `audit_events` and
    # `idempotency_receipts`, read in one database snapshot, in the canonical checkpoint row shape.
    # Every row carries `company_id`."
    expect(response.status).to eq(200)
    exported = checkpoint_from(response)
    expect(exported.rows.keys).to match_array(Timekeeping::Handoff::Checkpoint::TABLES.keys)
    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(exported.rows.transform_values(&:size)).to eq(
      "entries" => 2, "reservations" => 0, "invoice_operations" => 0, "entry_audits" => 2, "idempotency_records" => 2,
      "service_idempotency_receipts" => 0
    )
    %w[entries entry_audits idempotency_records].each do |table|
      expect(exported.rows.fetch(table).map { |row| row["company_id"] }).to contain_exactly(11, 22), table
    end
    expect(exported.rows.values.flatten.pluck("company_id")).to all(be_a(Integer))
    expect(exported.rows.fetch("idempotency_records").pluck("key"))
      .to contain_exactly("export-key-11", "export-key-22")
  end

  # "Load: "replaces the incoming owner's tables in one transaction", so
  # loading the same checkpoint twice gives equal counts and checksums."
  # An operator also re-runs a load whose first attempt timed out after it had
  # already committed, so the second load must not duplicate any row.
  it "loads the same populated two-company checkpoint twice with equal counts, checksums and stored rows" do
    # Two companies, so a row attached to the wrong company changes the digest.
    # The jsonb decimals are finer than a Float, so a lossy load changes them.
    decimals = {
      "entries" => { "source_metadata" => { "nested" => { "n" => BigDecimal("1.00000000000000000001") } } },
      "entry_audits" => { "after" => { "duration" => BigDecimal("60.000000000000000001") } }
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: merge_handoff_checkpoint_tables(
      handoff_checkpoint_tables(company_id: 1, id: 7, overrides: decimals),
      handoff_checkpoint_tables(company_id: 2, id: 8, overrides: decimals)
    ))
    Timekeeping::Admission.fence!

    first_status = handoff_request(:checkpoint_load, body: checkpoint.to_json).status
    first = checkpoint_from(response)
    rows_after_first = handoff_stored_rows
    second_status = handoff_request(:checkpoint_load, body: checkpoint.to_json).status
    second = checkpoint_from(response)

    expect([first_status, second_status]).to eq([200, 200])
    expect(first.digest).to eq(checkpoint.digest)
    expect(second.digest).to eq(first.digest)
    expect(Timekeeping::Handoff::Checkpoint.verify(second)).to eq([])
    expect(handoff_stored_rows).to eq(rows_after_first)
    expect([Entry.count, Reservation.count, InvoiceOperation.count, AuditEvent.count, IdempotencyReceipt.count])
      .to eq([2, 2, 2, 2, 2])
    # Stored text, not decoded values: a decoded comparison hides decimal rounding.
    expect(Entry.connection.select_values("SELECT source_metadata::text FROM entries ORDER BY id"))
      .to eq(['{"nested": {"n": 1.00000000000000000001}}'] * 2)
    expect(Entry.connection.select_values("SELECT after::text FROM audit_events ORDER BY id"))
      .to eq(['{"duration": 60.000000000000000001}'] * 2)

    handoff_request(:checkpoint_export)
    expect(response.status).to eq(200)
    exported = checkpoint_from(response)
    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(exported.digest).to eq(checkpoint.digest)
    expect(exported.rows.fetch("entry_audits").map { |row| [row["company_id"], row["id"]] })
      .to contain_exactly([1, 7], [2, 8])
  end

  # Acceptance: "Populated audits, idempotency receipts and operation receipts
  # round-trip between the two stores unchanged"
  # A row Timekeeping held before the load is not in the monolith's checkpoint,
  # so it must not survive into the export. The rows of one company must come
  # back under that company and no other.
  it "replaces stale rows with the monolith checkpoint file and exports its rows back unchanged" do
    stale = Entry.create!(id: 987_654, company_id: 424_242, user_id: 1, project_id: 2, work_date: "2026-03-02",
                          duration: 15.0, note: "Stale", bill_status: "unbilled", source: "manual", source_metadata: {})
    Timekeeping::Admission.fence!
    body = handoff_monolith_checkpoint_json
    source = Timekeeping::Handoff::Checkpoint.from_json(body)
    by_company = ->(rows) { rows.group_by { |row| row["company_id"] }.transform_values { |list| list.sort_by(&:to_s) } }
    expect(Timekeeping::Handoff::Checkpoint.verify(source)).to eq([])
    expect(source.rows.values.flatten.pluck("company_id").uniq.size).to be >= 2
    %w[invoice_operations entry_audits idempotency_records].each do |table|
      expect(by_company.call(source.rows.fetch(table)).keys.size).to be >= 2, "#{table} fixture covers two companies"
    end

    handoff_request(:checkpoint_load, body:)
    expect(response.status).to eq(200)
    handoff_request(:checkpoint_export)
    expect(response.status).to eq(200)
    exported = checkpoint_from(response)

    expect(exported.digest).to eq(source.digest)
    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(Entry.exists?(stale.id)).to be(false)
    Timekeeping::Handoff::Checkpoint::TABLES.each_key do |table|
      expect(exported.rows.fetch(table).map(&:to_a).sort_by(&:to_s))
        .to eq(source.rows.fetch(table).map(&:to_a).sort_by(&:to_s)), "#{table} rows changed in the round trip"
      expect(exported.rows.fetch(table).map { |row| Timekeeping::Handoff::Checkpoint.encode_row(table, row) })
        .to match_array(source.rows.fetch(table).map { |row| Timekeeping::Handoff::Checkpoint.encode_row(table, row) })
      expect(by_company.call(exported.rows.fetch(table))).to eq(by_company.call(source.rows.fetch(table))), table
    end
  end

  # "Timekeeping exports its entries, reservations, invoice operations, audit
  # rows and idempotency receipts in the canonical checkpoint row shape, each
  # row with company_id"
  it "keeps each loaded row under its own company when two companies share an invoice id and receipt key" do
    shared = { "reservations" => { "invoice_id" => 500 }, "invoice_operations" => { "invoice_id" => 500 },
               "idempotency_records" => { "key" => "same-key" } }
    tables = merge_handoff_checkpoint_tables(
      handoff_checkpoint_tables(company_id: 1, id: 101, overrides: shared),
      handoff_checkpoint_tables(company_id: 2, id: 202, overrides: shared)
    )
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables:)
    Timekeeping::Admission.fence!

    handoff_request(:checkpoint_load, body: checkpoint.to_json)
    expect(response.status).to eq(200)
    handoff_request(:checkpoint_export)
    expect(response.status).to eq(200)
    exported = checkpoint_from(response)

    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(exported.digest).to eq(checkpoint.digest)
    tables.each_key do |table|
      expect(exported.rows.fetch(table).map { |row| row["company_id"] }.sort).to eq([1, 2]), table
    end
    expect(exported.rows.fetch("invoice_operations").to_h { |row| [row["company_id"], row["desired_entry_ids"]] })
      .to eq(1 => [101], 2 => [202])
    expect(exported.rows.fetch("entries").to_h { |row| [row["id"], row["company_id"]] }).to eq(101 => 1, 202 => 2)
  end

  # "Timekeeping's load replaces its tables in one transaction"
  it "rolls back the whole load when a reservation fails to insert after the entries were replaced" do
    now = Time.utc(2026, 3, 2, 9)
    Entry.create!(id: 41, company_id: 1, version: 2, project_id: 5, user_id: 7, work_date: Date.new(2026, 3, 2),
                  duration: 60.0, note: "kept", bill_status: "unbilled", created_at: now, updated_at: now)
    Reservation.create!(company_id: 1, entry_id: 41, invoice_id: 9, state: "committed", disposition: "active",
                        operation_id: SecureRandom.uuid, created_at: now)
    Timekeeping::Admission.fence!

    handoff_request(:checkpoint_export)
    expect(response.status).to eq(200)
    rows = checkpoint_from(response).rows.transform_values { |list| list.map(&:dup) }
    rows["entries"] = rows["entries"].map { |row| row.merge("note" => "replaced") }
    # A reservation for an entry the checkpoint does not hold breaks the
    # composite foreign key only after the entries have been rewritten.
    rows["reservations"] = rows["reservations"].map { |row| row.merge("entry_id" => 999) }

    handoff_request(:checkpoint_load, body: Timekeeping::Handoff::Checkpoint.build(tables: rows).to_json)

    expect(response.status).not_to eq(200)
    expect(Entry.pluck(:id, :note, :version)).to eq([[41, "kept", 2]])
    expect(Reservation.pluck(:entry_id, :invoice_id)).to eq([[41, 9]])
  end

  describe "load refusals" do
    # Each row names the body it sends, any state it needs only while it runs,
    # the answer it must get, and checks of its own beyond "nothing changed".
    # Every body is built from one export taken while the stored entry matched
    # it, so a load of that export would succeed: each row fails only on the
    # one guard it names.
    def load_refusal_rows(exported, stored_version, digest_before)
      tampered = JSON.parse(exported)
      tampered.fetch("tables").fetch("entries").first.find { |column, _| column == "note" }[1] =
        ["str", "tampered-secret-note"]

      older_rows = Timekeeping::Handoff::Checkpoint.from_json(exported).rows.transform_values { |list| list.map(&:dup) }
      older_rows["entries"] = older_rows["entries"].map { |row| row.merge("version" => stored_version - 1) }

      unknown_key = JSON.parse(exported)
      unknown_key.fetch("tables")["outbox_snapshots"] = []

      [
        # "Recompute the digest inside the transaction and roll back on a mismatch."
        # The refusal answers with a reason only, so a row value never reaches a response.
        { name: "tampered digest", body: JSON.generate(tampered), answer: [409, { "reason" => "handoff_refused" }],
          extra: lambda {
            expect(response.body).not_to include("tampered-secret-note")
            handoff_request(:checkpoint_export)
            expect(checkpoint_from(response).digest).to eq(digest_before)
          } },
        # "Refuse any entry whose current version is higher than its checkpoint version."
        { name: "older entry version", body: Timekeeping::Handoff::Checkpoint.build(tables: older_rows).to_json,
          answer: [409, { "reason" => "handoff_refused" }] },
        # A table key with no home must be refused before any delete, never skipped.
        { name: "unknown table in an export", body: JSON.generate(unknown_key),
          answer: [400, { "reason" => "invalid_request" }] },
        { name: "unknown table with no digest", body: JSON.generate(
          "tables" => Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }.merge("admission" => []),
          "digest" => {}
        ), answer: [400, { "reason" => "invalid_request" }] },
        { name: "unparseable body", body: "{not json", answer: [400, { "reason" => "invalid_request" }] },
        # A load runs only while admission is fenced, because replacing the
        # tables deletes every row the checkpoint lacks, such as an entry
        # written after the export.
        { name: "admission open", body: exported, answer: [409, { "reason" => "handoff_refused" }],
          during: ->(&deliver) { open_admission_for_load_refusal(&deliver) } }
      ]
    end

    def open_admission_for_load_refusal
      Timekeeping::Admission.admit!(generation: 1)
      yield
    ensure
      Timekeeping::Admission.fence!
    end

    it "refuses each invalid load with its reason and leaves every table as it was seeded" do
      entry = checkpoint_spec_entry("Design review", version: 3)
      AuditEvent.create!(company_id: 1, entry_id: entry.id, actor_type: "user", actor_id: 7, action: "create",
                         before: nil, after: { "note" => "Design review" }, entry_created_at: entry.created_at,
                         created_at: Time.current)
      Reservation.create!(company_id: 1, entry_id: entry.id, invoice_id: 9, state: "committed", disposition: "active",
                          operation_id: SecureRandom.uuid, created_at: Time.current)
      IdempotencyReceipt.create!(company_id: 1, actor_type: "user", actor_id: 7, operation: "create", key: "seeded",
                                 fingerprint: "f", status: 201, body: "{}", created_at: Time.current)
      Timekeeping::Admission.fence!
      handoff_request(:checkpoint_export)
      expect(response.status).to eq(200)
      exported = response.body
      # Written after the export: a load that deleted before failing and kept
      # the delete would lose this row.
      checkpoint_spec_entry("Written after export")

      before = handoff_stored_rows
      expect(Entry.order(:id).pluck(:note, :version)).to eq([["Design review", 3], ["Written after export", 1]])
      expect(before.transform_values(&:size)).to eq(
        "entries" => 2, "reservations" => 1, "invoice_operations" => 0, "audit_events" => 1,
        "idempotency_receipts" => 1, "service_idempotency_receipts" => 0, "outbox_snapshots" => 0
      )
      handoff_request(:checkpoint_export)
      digest_before = checkpoint_from(response).digest

      load_refusal_rows(exported, entry.version, digest_before).each do |row|
        send_load = -> { handoff_request(:checkpoint_load, body: row.fetch(:body)) }
        row.fetch(:during, ->(&deliver) { deliver.call }).call(&send_load)

        expect([row.fetch(:name), response.status, response.parsed_body]).to eq([row.fetch(:name), *row.fetch(:answer)])
        expect([row.fetch(:name), handoff_stored_rows, Timekeeping::Admission.current.generation])
          .to eq([row.fetch(:name), before, nil])
        row[:extra]&.call
      end
    end
  end
end
